async function melody1_2() {
  YYYYLog("1-2", "part")
  const soBeChars = [
    "uuu dd uuuuu uuu uuu dd uuuuuu uuu ",
    "uuu dd uuuuuu u uuu dd uuuuuuuuu dd、",
    "uuuuuuuu uuuuuuuuu uuuuuuuu du uuu dd ",
    "uuuuuu uuuuuu uuu dd uuuuuuuu uuuuuuuu。",
    "uuu dd uuuuuu uuuuuuuuu uuu dd uuuu uuuuuu ",
    "uuu dd uuuuu uuuuuuu uuu dd uuuuuu uuuuuu、",
    "uuuuuu uuu uu duuuuu uuu dd uuuuuuuu d uuuuu ",
    "uuuu u u uuu dd uuuu uuuu uuu dd uuuuuu uuuuuu、",
    "uuu dd uuuu duuuuu uuu dd uuuuuuuu duu uuu dd ",
    "uuuuuu d uuu dd uuuu uuuu uuu dd uuuuuu duuuu？",
    "uuu dd uuuuu d uuu dd uuuuuu ",
    "uuu uuu dd uuuuuu uuuuuuuu、",
    "uuuu duuuu dd dd uuuuuuu ",
    "duuu duuu uu uuu dd uuuuuu du、",
    "uuuuu duu uuuu uuuuu uuu dd uuuuu duuuuu uuu ",
    "dd uuuu du uuu dd uuuuuu uuu uuu dd uuuuu duuuuu。",
  ]
  const songlist = [
    "DSC_9998.mp4",
    "∴",
    "確執",
    "∴∴",
    "想い出の枯葉が飛び去る前に",
    "鵺",
    "∴∴∴[short]",
    "センプレ",
    "偶/奇",
    "dsc_9997.m4v",
    "∴∴∴",
    "未知数",
    "M.A.Z.",
    "線分でわけて",
    "呪縛",
    "∴∴∴∴",
  ]
  //サイドバー暗号準備
  const leftSideCode = new MenuBarCode("ここの暗号どうしようかな", "left");
  const bottomSideCode = new MenuBarCode("スパゲッティコード", "bottom");
  const codeTime = (60 / specialsong.bpm) + 0.05;
  YYYYLog("Left Side and Bottom Side Code","coder1");
  //モールス暗号準備
  const morse = new MorseExecuter("right");
  //ヘッダー暗号準備
  const header = document.querySelector("header");
  YYYYLog("Showed Header","coder1");
  header.style.display = "inline";
  //ヘッダー表示
  displayItemWithGlitch(header);
  const title = document.querySelector("header>div:nth-child(2)>a:nth-child(2)");
  await specialsong.wait(0.1);
  //サイドバー暗号実行
  leftSideCode.run(codeTime * 2);
  bottomSideCode.run(codeTime * 2)
  //モールス暗号実行
  morse.execute("ーーー・ー ・ ・・ ー・・ーー ー・ーーー ー・ー・ー ・ー ーーーー ・・ー ".repeat(3))
  //ヘッダー暗号実行
  for (let i = 0; i < soBeChars.length; i++) {
    const angou = soBeChars[i];
    const songName = songlist[i];
    title.innerText = angou.replace(/u/g, "∴").replace(/d/g, "∵");
    document.title = `${songName} / 全てあなたの所以です。 | 全て歌詞の所為です。`;
    YYYYLog(`${songName},${angou}`,"coder1-changed");
    await specialsong.waitPerMeadow(1);
  }
  unDisplayItemWithGlitch(header);
  YYYYLog("Hided Header","coder1");
  await specialsong.wait(0.1);
  title.innerText = "全てまめーんの所為です。"
}

async function melody2A() {
  YYYYLog("2A", "part")
  const speed = (60 / specialsong.bpm) * 12;
  new RiseingText(false, `雨上がりの足跡の側、`, FONTSIZE, speed);
  await specialsong.waitPerMeadow(2);
  //案: Fのフォントを変更
  new RiseingText(true, `賞味期限の切れた<span id="f-shoumikigenngire">F</span>の様、`, FONTSIZE, speed);
  await specialsong.waitPerMeadow(2);
  //案: 人を消す
  new RiseingText(true, `亡くした<span id="hito">人</span>を呪い蔑んで、`, FONTSIZE, speed);
  await specialsong.waitPerMeadow(1.25);
  document.querySelector("#hito").innerText = "？";
  await specialsong.waitPerMeadow(0.75);
  new RiseingText(false, `永劫に溺れていたのか。`, FONTSIZE, speed);
  await specialsong.waitPerMeadow(2);
  new RiseingText(false, `そして墓場ごと掘り返して、`, FONTSIZE, speed);
  await specialsong.waitPerMeadow(2);
  //案: イデアを色あせる
  new RiseingText(true, `色褪せた<span style="color:rgba(192, 192, 156, 1);">イデア</span>の先では、`, FONTSIZE, speed);
  await specialsong.waitPerMeadow(2);
  //案: Ѥを文字化けさせる
  const habaText = new RiseingText(true, `<span id="haba"></span>られるモノが遊歩する、`, FONTSIZE, speed);
  (async () => {
    //文字化け
    const haba = document.querySelector("#haba")
    const HABAS = ["Ѥ", "\u0463", "\u0462", "\u0465", "\u0466", "憚", "？"]
    while (habaText.rising) {
      //HABAS内をサイクル
      haba.innerText = HABAS[(Math.abs(HABAS.indexOf(haba.innerText)) + 1) % HABAS.length];
      await specialsong.wait(0.1);
    }
  })()
  await specialsong.waitPerMeadow(2);
  //案: 「何か」の何かを間違える
  const noOpac = (s) => `<span style="opacity:0;">${s}</span>`
  const nanika1 = new RiseingText(true, `${noOpac("何か")}が間違っていた。`, FONTSIZE, speed * 0.77, "bottom");
  const nanika2 = new RiseingText(true, `何か${noOpac("が間違っていた。")}`, FONTSIZE, speed * 0.77, "top");
  await specialsong.waitPerMeadow(1.15);
  nanika1.element.style.display = "none";
  nanika2.element.style.display = "none";
  await specialsong.waitPerMeadow(0.85);
}

async function melody2Hook() {
  const header = document.querySelector("header");
  const title = document.querySelector("header>div:nth-child(2)>a:nth-child(2)");
  // 全て歌詞の所為です。にオールグッバイ！これからは全てあなたの所以です。の時代だ！
  (async()=>{
    const heImg = document.querySelector("header>#subekashi-header>a")
    //画像エレメント複製
    heImg.innerHTML += heImg.innerHTML
    //全て歌詞の所為です。にさよならを告げる
    const sbks = document.querySelector('[name="thumbnail"]');
    sbks.style.display="none";
    //全てあなたの所以です。を迎え入れる準備
    const sbye = document.querySelector('[name="thumbnail"]:nth-child(2)');
    sbye.id = "sbye";
    sbye.src = "https://yt3.googleusercontent.com/I0W-LCF0SWg0WrUbolsqXU5Z8avwGSYmXaW5-dT3dlEGEkZ_0bxz6WmxrGd0wnaIl6ZtIk38NA";
    sbye.alt = "全てあなたの所以です。のロゴ";
    title.innerText = "全てあなたの所以です。"
  })()
  // 全てあなたの所以です。にオールグッバイ！これからは全て歌詞の所為です。の時代だ！
  function returnToSBKS(){
    //全てあなたの所以です。にさよならを告げる
    document.querySelector("#sbye").remove();
    //全て歌詞の所為です。を迎え入れる準備
    document.querySelector('[name="thumbnail"]').style.display = "";
    title.innerText = "全て歌詞の所為です。"
  }
  // ちょっと早くしてみる
  const speed = (60 / specialsong.bpm) * 8;
  YYYYLog("2Hook", "part")
  //ヒント: [ー・ー・・　・ー　・ー・ー(　), ーー・ーー　・ー・・(・), ーー・ーー　・ー・・・(ー)]
  const colorI = [
    'blue', 'red', 'red', 'blue', 'blue', 'yellow',
    'blue', 'red', 'red', 'red', 'blue', 'yellow'
  ][Symbol.iterator]();
  /** RiseingTextを生成したのち配列から色を取り出し適用する */
  const genColorRiseText = (...args)=>{
    const t = new RiseingText(...args);
    t.element.style.color = colorI.next().value;
    return t;
  }
  genColorRiseText(false, `蠱惑の草の根も、`, FONTSIZE, speed, "bottom");
  genColorRiseText(false, `遡れる者も、`, FONTSIZE, speed, "top");
  await specialsong.waitPerMeadow(2);
  genColorRiseText(false, `渡り行く時間軸も、`, FONTSIZE, speed, "bottom");
  genColorRiseText(false, `廃れた誰かの顔も、`, FONTSIZE, speed, "top");
  await specialsong.waitPerMeadow(2);
  genColorRiseText(false, `何かの住まう理も、`, FONTSIZE, speed, "bottom");
  genColorRiseText(false, `緋色に見えた星も、`, FONTSIZE, speed, "top");
  await specialsong.waitPerMeadow(2);
  const subeyue1 = new RiseingText(false, `全てあなたの所以です。`, FONTSIZE, speed * 2, "bottom");
  await specialsong.waitPerMeadow(1.5);
  subeyue1.element.innerText = "全て下→上の順番です。"
  unDisplayItemWithGlitch(subeyue1.element)
  await specialsong.waitPerMeadow(.5);
  genColorRiseText(false, `穢れゆく詐欺師も、`, FONTSIZE, speed, "bottom");
  genColorRiseText(false, `三の火の在処も、`, FONTSIZE, speed, "top");
  await specialsong.waitPerMeadow(2);
  genColorRiseText(false, `疲弊した破落戸も、`, FONTSIZE, speed, "bottom");
  genColorRiseText(false, `ユメウツツの望遠鏡も、`, FONTSIZE, speed, "top");
  await specialsong.waitPerMeadow(2);
  genColorRiseText(false, `偽物の∴∴∴∴も、`, FONTSIZE, speed, "bottom");
  genColorRiseText(false, `傾いた∴∴∴∴も、`, FONTSIZE, speed, "top");
  await specialsong.waitPerMeadow(1.75);
  header.style.opacity = "";
  header.style.display = "";
  YYYYLog("Showed Header","melody2hook");
  await specialsong.waitPerMeadow(1.25);
  header.style.opacity = "0";
  YYYYLog("Hided Header","melody2hook");
  await specialsong.waitPerMeadow(1);
  //3拍子
  specialsong.meter = 3
  specialsong.bpm = 198;
  YYYYLog("Changed meter and bpm (4:132 -> 3:198)","melody2hook");
  returnToSBKS();
}

