//モールス信号ライブラリ
class MorseBarLibrary {
  static inited = false;
  static SIDE = ["left", "right", "top", "bottom"];
  /**
   * @param {MorseSetting} morseSetting
   */
  static init(morseSetting = new MorseSetting()) {
    this.inited = true;
    this._genDivs();
    this._setCSS();
    this.setting(morseSetting);
  }
  static _setCSS() {
    const style = document.createElement("style");
    style.innerHTML = `body{--morse-width:10px;--morse-speed:0.5s;--morse-zindex:1}#left-morse{--back:red;position:absolute;width:var(--morse-width);z-index:var(--morse-zindex);height:100%;left:0;top:0}#right-morse{--back:blue;position:absolute;width:var(--morse-width);z-index:var(--morse-zindex);height:100%;right:0;top:0}#top-morse{--back:yellow;position:absolute;height:var(--morse-width);z-index:var(--morse-zindex);width:100%;top:0;left:0}#bottom-morse{--back:green;position:absolute;height:var(--morse-width);z-index:var(--morse-zindex);width:100%;bottom:0;left:0}#left-morse>*,#right-morse>*{background-color:var(--back);position:absolute;width:100%}#top-morse.morse>*,#bottom-morse.morse>*{background-color:var(--back);position:absolute;height:100%}#left-morse.morse>*:nth-child(1),#right-morse.morse>*:nth-child(1){animation:lr-morse-top var(--morse-speed) linear 0s}#left-morse.morse>*:nth-child(2),#right-morse.morse>*:nth-child(2){animation:lr-morse-center var(--morse-speed) linear 0s}#left-morse.morse>*:nth-child(3),#right-morse.morse>*:nth-child(3){animation:lr-morse-down var(--morse-speed) linear 0s}#top-morse.morse>*:nth-child(1),#bottom-morse.morse>*:nth-child(1){animation:tb-morse-top var(--morse-speed) linear 0s}#top-morse.morse>*:nth-child(2),#bottom-morse.morse>*:nth-child(2){animation:tb-morse-center var(--morse-speed) linear 0s}#top-morse.morse>*:nth-child(3),#bottom-morse.morse>*:nth-child(3){animation:tb-morse-down var(--morse-speed) linear 0s}@keyframes lr-morse-top{0%{top:0%;height:33.3%}100%{top:0%;height:0%}}@keyframes lr-morse-center{0%{top:47.5%;height:5%}100%{top:16.7%;height:66.6%}}@keyframes lr-morse-down{0%{top:66.6%;height:33.3%}100%{top:100%;height:0%}}@keyframes tb-morse-top{0%{left:0%;width:33.3%}100%{left:0%;width:0%}}@keyframes tb-morse-center{0%{left:47.5%;width:5%}100%{left:16.7%;width:66.6%}}@keyframes tb-morse-down{0%{left:66.6%;width:33.3%}100%{left:100%;width:0%}}`;
    document.body.appendChild(style)
  }
  static _genDivs() {
    this.SIDE.forEach((s) => {
      const div = document.createElement("div");
      div.id = `${s}-morse`;
      div.innerHTML = `<div></div>`.repeat(3);
      document.body.appendChild(div);
    });
  }
  /**
   * @param {MorseSetting} morseSetting
   */
  static setting(morseSetting) {
    if (!this.inited) this.init();
    const bS = document.body.style;
    bS.setProperty("--morse-width", `${morseSetting.width}px`);
    bS.setProperty("--morse-speed", `${morseSetting.speed}s`);
    bS.setProperty("--morse-zindex", `${morseSetting.zIndex}`);
    this.SIDE.forEach((s) => {
      document
        .getElementById(`${s}-morse`)
        .style.setProperty("--back", morseSetting[`${s}Color`]);
    });
  }
  /** @param {"left"|"right"|"top"|"bottom"} side*/
  static start(side) {
    if (!this.inited) this.init();
    const bar = document.getElementById(`${side}-morse`);
    bar.classList.remove("morse");
    const rAF = window.requestAnimationFrame;
    rAF(() => rAF(() => bar.classList.add("morse")));
  }
  /** @param {"left"|"right"|"top"|"bottom"} side*/
  static end(side) {
    if (!this.inited) this.init();
    const bar = document.getElementById(`${side}-morse`);
    bar.classList.remove("morse");
  }
}
/**
 * @example
 * const a = new MorseExecuter("left");
 * a.execute("ー・・ ".repeat(10));
 * const b = new MorseExecuter("top");
 * b.execute("・・・・ ".repeat(10));
 * const c = new MorseExecuter("right");
 * c.execute("ーーー ".repeat(10));
 * const d = new MorseExecuter("bottom");
 * d.execute("ー・・ー ".repeat(10));
 */
class MorseExecuter {
  morse = "";
  chars = {
    short: "・",
    long: "ー",
    separete: " ",
  };
  times = {
    short: 0.15,
    long: 0.25,
    separete: 0.15,
  };
  /**@type {Promise<null>?} */
  task = null;
  executing = false;
  /**
   * @param {"left"|"right"|"top"|"bottom"} side
   * @param {MorseExecuter?} copySetting
   */
  constructor(side, copySetting) {
    /**@type {"left"|"right"|"top"|"bottom"} */
    this.side = side;
    if (!!copySetting) {
      this.chars = copySetting.chars;
      this.times = copySetting.times;
    }
  }
  calcel() {
    this.executing = false;
  }

  /**
   * @param {string} morse
   */
  execute(morse) {
    this.executing = true;
    this.task = new Promise((reso, reje) => {
      const chars = morse.split("");
      const charCall = (callCount) =>
        new Promise((r) => {
          const char = chars[callCount];
          const charType = Object.entries(this.chars).find(
            (kv) => kv[1] === char
          )[0];
          const time = this.times[charType];
          //止めるタイミングではstartしない
          if (charType !== "separete") MorseBarLibrary.start(this.side);
          else MorseBarLibrary.end(this.side);
          setTimeout(async () => {
            if (callCount === chars.length - 2) r();
            else r(await charCall(callCount + 1));
          }, time * 1000);
        });
      charCall(0).then(() => {
        MorseBarLibrary.end(this.side);
        this.executing = false;
        reso();
      });
    });
    return this.task;
  }
}
class MorseSetting {
  width = 10;
  speed = 0.5;
  zIndex = 1;
  leftColor = "red";
  rightColor = "blue";
  topColor = "yellow";
  bottomColor = "green";
  constructor() { }
  /**@param {number} width  */
  Width(width) {
    this.width = width;
    return this;
  }
  /**@param {number} speed  */
  Speed(speed) {
    this.speed = speed;
    return this;
  }
  /**@param {number} zIndex  */
  ZIndex(zIndex) {
    this.zIndex = zIndex;
    return this;
  }
  /**
   * @param {"left"|"right"|"top"|"bottom"} side
   * @param {string} color
   */
  Side(side, color) {
    this[`${side}Color`] = color;
    return this;
  }
  /**@param {string} color  */
  LeftColor(color) {
    return this.Side("left", color);
  }
  /**@param {string} color  */
  RightColor(color) {
    return this.Side("right", color);
  }
  /**@param {string} color  */
  TopColor(color) {
    return this.Side("top", color);
  }
  /**@param {string} color  */
  BottomColor(color) {
    return this.Side("bottom", color);
  }
}

/**左または下のボタンたちで暗号作る(???????) */
class MenuBarCode {
  /** 
   * @param {string} noCryptedCode
   * @param {"left"|"bottom"} side 
   */
  constructor(noCryptedCode, side) {
    if (side === "left")
      this.sidebar = document.querySelector("aside>table>tbody")
    else this.sidebar = document.querySelector("#tab_bar");
    if (!this.sidebar) throw new Error("Menu not found")
    /**@type {HTMLElement[]} */
    this.buttons = Array.from(this.sidebar.children)
    /** ボタン数。よく参照するので短い名前。 */
    this.bco = this.buttons.length;
    this.noCryptedCode = noCryptedCode;
    /**@type {string[]} ボタン数桁の2進数文字列の全体コード配列*/
    this.code = [];
    this.max = (2 ^ this.bco) - 1
    noCryptedCode.split("").map((v) => {
      const binChar = v.charCodeAt(0).toString(2);
      //追加する0の文字数を計算
      const add0 = (this.bco - binChar.length % this.bco) % this.bco;
      const code = "0".repeat(add0) + binChar;
      for (let i = 0; i < code.length / this.bco; i++) {
        //ボタン数文字で区切る
        this.code.push(code.substring(i * this.bco, (i + 1) * this.bco))
      }
    });
  }
  /** 
   * @param {number} speed 1回表示する時間(秒)
   */
  run(speed) {
    this.index = -1;
    this.speed = speed;
    const rep = () => {
      if (this.next()) {
        setTimeout(() => {
          this.index++;
          rep();
        }, this.speed * 1000);
      }
    }
    rep();
  }
  /**
   * 直接暗号を表示する。
   * @returns {boolean} 暗号の表示が完了していないか。
   */
  next(index = this.index + 1) {
    if (this.code.length === index) {
      this.buttons.forEach((el, i) => {
        el.style.opacity = "";
      })
      return false;
    };
    const code = this.code[index];
    if (code.length !== this.buttons.length)
      throw new Error("Code Length and Buttons Length aren't same");
    this.buttons.forEach((el, i) => {
      el.style.opacity = code[i];
    })
    return true;
  }
}